/**
 * Minimal Worker in front of Static Assets + per-token MCP gateway (OG-028G).
 * NOTE: matched static files are served by the assets layer without invoking
 * this Worker — cache + security headers for them come from the `_headers`
 * file generated by `scripts/copy-dist.mjs`. The header logic below applies to
 * Worker-served responses (e.g. `/health`, SPA fallback misses).
 * - `index.html` is never cached (shell with env bootstrap).
 * - Hashed assets are immutable for 1 year (mirrors upstream `staticEditor.ts`).
 * - SPA fallback serves `index.html` for navigations only.
 * - `/health` for uptime checks.
 * - `/mcp` (POST, Bearer) and `/bridge` (WebSocket, `?token=`): MCP gateway
 *   backed by `GatewayDO`, one stub per Souv login (token hash). No Souv code
 *   changes required: tokens are verified against `{SOUV_API}/api/ograf/projects`.
 */
import { bearerToken, sha256Hex } from './auth';
import { EDITOR_CSP } from './csp';
import { GatewayDO } from './gatewayDO';

export { GatewayDO };

interface GatewayEnv extends Record<string, unknown> {
  GATEWAY?: DurableObjectNamespace;
}

async function gatewayStub(
  env: GatewayEnv,
  token: string | null,
): Promise<{ stub: DurableObjectStub } | { response: Response }> {
  if (!token) {
    return {
      response: Response.json(
        {
          error:
            'Missing Souv credential. Send Authorization: Bearer <token> (or ?token= for the tab bridge).',
        },
        { status: 401 },
      ),
    };
  }
  const namespace = env.GATEWAY;
  if (!namespace) {
    return { response: new Response('Gateway binding missing', { status: 500 }) };
  }
  return { stub: namespace.get(namespace.idFromName(`gateway-${await sha256Hex(token)}`)) };
}

export default {
  async fetch(request: Request, env: Record<string, unknown>): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname === '/health' || url.pathname === '/api/health') {
      return Response.json({ ok: true, worker: 'ograf-studio-cloud', assets: true, mcp: '/mcp' });
    }
    if (url.pathname === '/mcp') {
      const routed = await gatewayStub(env as GatewayEnv, bearerToken(request));
      if ('response' in routed) return routed.response;
      return routed.stub.fetch(request);
    }
    if (url.pathname === '/bridge') {
      const routed = await gatewayStub(env as GatewayEnv, url.searchParams.get('token'));
      if ('response' in routed) return routed.response;
      return routed.stub.fetch(request);
    }
    // Let the assets binding serve everything else (including SPA fallback).
    const assets = (env as { ASSETS?: { fetch: typeof fetch } }).ASSETS;
    if (!assets) return new Response('Assets binding missing', { status: 500 });
    const response = await assets.fetch(request);
    const pathname = url.pathname;
    const headers = new Headers(response.headers);
    if (pathname === '/' || pathname.endsWith('/index.html')) {
      headers.set('Cache-Control', 'no-store');
    } else if (response.status === 200 && !headers.get('Cache-Control')) {
      headers.set('Cache-Control', 'public, max-age=31536000, immutable');
    }
    // OG-025: static editor ships no credentials; harden with minimal headers that
    // do not break canvas, fonts, or `html-to-image`. Tighten `frame-ancestors`
    // per Souv embedding policy at deploy time.
    headers.set('X-Content-Type-Options', 'nosniff');
    headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
    if (!headers.get('Content-Security-Policy')) {
      headers.set('Content-Security-Policy', EDITOR_CSP);
    }
    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  },
};
